<script setup lang="ts">
// Login view (generated by engineering-platform frontend-auth asset)
// Real backend call: POST /api/auth/login. Frontend never verifies tokens/BCrypt.
import { ref } from 'vue';
import { useRouter, useRoute } from 'vue-router';
import { useAuthStore } from '../stores/auth';
import { ApiError } from '../api/request';

const auth = useAuthStore();
const router = useRouter();
const route = useRoute();

const username = ref('');
const password = ref('');
const loading = ref(false);
const error = ref<string | null>(null);

async function submit(): Promise<void> {
  if (loading.value) {
    return;
  }
  error.value = null;
  loading.value = true;
  try {
    await auth.login(username.value, password.value);
    const redirect = typeof route.query.redirect === 'string' ? route.query.redirect : '/';
    router.push(redirect);
  } catch (e) {
    // never leak backend internals; stable message only
    error.value = e instanceof ApiError ? e.message : 'login failed, please try again';
  } finally {
    loading.value = false;
  }
}
</script>

<template>
  <div class="login-page">
    <el-card class="login-card">
      <h1 class="login-title">Engineering Platform</h1>
      <el-form label-position="top" @submit.prevent="submit">
        <el-form-item label="Username">
          <el-input v-model="username" data-testid="login-username" autocomplete="username" />
        </el-form-item>
        <el-form-item label="Password">
          <el-input
            v-model="password"
            type="password"
            data-testid="login-password"
            autocomplete="current-password"
            show-password
            @keyup.enter="submit"
          />
        </el-form-item>
        <el-alert v-if="error" :title="error" type="error" :closable="false" class="login-error" data-testid="login-error" />
        <el-button
          type="primary"
          native-type="submit"
          :loading="loading"
          data-testid="login-submit"
          class="login-submit"
        >
          Sign in
        </el-button>
      </el-form>
    </el-card>
  </div>
</template>

<style scoped>
